PRAGMA foreign_keys = ON;
CREATE TABLE source (source_id TEXT PRIMARY KEY, owner TEXT NOT NULL, username TEXT NOT NULL, host TEXT NOT NULL, root_path TEXT NOT NULL, access_state TEXT NOT NULL, first_seen_utc TEXT NOT NULL, notes TEXT);
CREATE TABLE system (system_id TEXT PRIMARY KEY, formula TEXT, host_material TEXT, mobile_species TEXT, dopant_species TEXT, site_label TEXT, cell_json TEXT, pbc_json TEXT, identity_status TEXT NOT NULL);
CREATE TABLE calculation (calculation_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES source, system_id TEXT REFERENCES system, source_path TEXT NOT NULL, calculation_type TEXT NOT NULL, method_json TEXT, status TEXT NOT NULL, scientific_acceptance TEXT NOT NULL, created_utc TEXT NOT NULL, notes TEXT);
CREATE TABLE artifact (artifact_id INTEGER PRIMARY KEY, calculation_id TEXT NOT NULL REFERENCES calculation, path TEXT NOT NULL, artifact_role TEXT NOT NULL, size_bytes INTEGER, mtime_utc TEXT, sha256 TEXT, parse_status TEXT NOT NULL, UNIQUE(calculation_id,path));
CREATE TABLE structure (structure_id INTEGER PRIMARY KEY, calculation_id TEXT NOT NULL REFERENCES calculation, frame_index INTEGER, natoms INTEGER, formula TEXT, positions_uri TEXT, energy_ev REAL, max_force_ev_ang REAL, source_artifact_id INTEGER REFERENCES artifact, UNIQUE(calculation_id,frame_index));
CREATE TABLE endpoint (endpoint_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES source, source_path TEXT NOT NULL, system_label TEXT, site_label TEXT, calculation_type TEXT NOT NULL, method_json TEXT, natoms INTEGER, energy_ry REAL, optimizer_evidence TEXT, quality_status TEXT NOT NULL, publication_role TEXT);
CREATE TABLE endpoint_quality (endpoint_id TEXT PRIMARY KEY REFERENCES endpoint, max_local_force_ry_au REAL, approx_max_force_ev_ang REAL, threshold_ev_ang REAL, threshold_status TEXT NOT NULL, parser_status TEXT NOT NULL, notes TEXT, checked_utc TEXT NOT NULL);
CREATE TABLE endpoint_provenance (endpoint_id TEXT PRIMARY KEY REFERENCES endpoint, input_sha256 TEXT NOT NULL, output_sha256 TEXT NOT NULL, input_size_bytes INTEGER, output_size_bytes INTEGER, final_energy_ry REAL, raw_host TEXT NOT NULL, raw_input_path TEXT NOT NULL, raw_output_path TEXT NOT NULL, provenance_status TEXT NOT NULL);
CREATE TABLE endpoint_identity (endpoint_id TEXT PRIMARY KEY REFERENCES endpoint, system_label TEXT NOT NULL, formula TEXT NOT NULL, natoms INTEGER NOT NULL, dopant_species TEXT NOT NULL, dopant_count INTEGER NOT NULL, host_counts TEXT NOT NULL, cell_source TEXT, pbc_status TEXT, identity_status TEXT NOT NULL);
CREATE TABLE trajectory (trajectory_id TEXT PRIMARY KEY, calculation_id TEXT NOT NULL REFERENCES calculation, n_images INTEGER, image_order_status TEXT, endpoint_identity_status TEXT, barrier_ev REAL, barrier_method TEXT, convergence_status TEXT, trajectory_uri TEXT);
CREATE TABLE result (result_id INTEGER PRIMARY KEY, calculation_id TEXT NOT NULL REFERENCES calculation, metric_name TEXT NOT NULL, value REAL, unit TEXT, uncertainty REAL, extraction_method TEXT, evidence_artifact_id INTEGER REFERENCES artifact);
CREATE TABLE quality_gate (gate_id TEXT NOT NULL, calculation_id TEXT NOT NULL REFERENCES calculation, status TEXT NOT NULL, evidence TEXT, checked_utc TEXT NOT NULL, PRIMARY KEY(gate_id,calculation_id));
CREATE TABLE publication_link (calculation_id TEXT NOT NULL REFERENCES calculation, manuscript_target TEXT NOT NULL, reviewer_item TEXT, claim_status TEXT NOT NULL, required_followup TEXT, PRIMARY KEY(calculation_id,manuscript_target));
